solution:
def most_fed(hunger: list[int], portions: list[int]) -> int:
    need = sorted(hunger)
    fed = 0                              # children in need[:fed] are satisfied
    for size in sorted(portions):
        if fed < len(need) and size >= need[fed]:
            fed += 1                     # smallest portion that fits the least hungry child
    return fed

perf.naive:
def most_fed(hunger: list[int], portions: list[int]) -> int:
    used = [False] * len(portions)
    fed = 0
    for need in sorted(hunger):          # scan every portion for the smallest unused fit
        best = -1
        for j, size in enumerate(portions):
            if not used[j] and size >= need and (best < 0 or size < portions[best]):
                best = j
        if best >= 0:
            used[best] = True
            fed += 1
    return fed
